import re,csv
R='data/inference_test/results/opus-5-5.csv'; stem='Kubiak Cunn 2009'
cols=open(R).readline().strip().split(',')
txt=open(f"data/papers_test/md_agents/{stem}.md",encoding='utf-8').read()
pages=txt.split('<!-- PAGE BREAK -->')
src="Kubiak, P.J. (2009) Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia 11(1): 131–165."
FIRE=dict(Fire_type='wildfire',Fire_season_categorical='Summer',Fire_severity_categorical='High')
FNOTE="fire 6-8 January 1994 (Fire_season derived from date); Fire_severity High from 'very high intensity' fires with 100% canopy scorch over a large proportion of the burnt area (pp. 133-136); rainfall not stated"
LCR=dict(Latitude='-33.75',Longitude='151.0833')
CODES={'R':'majority resprouted','K':'majority killed','r':'small proportion resprouted','k':'small proportion killed','pR':'probably resprouted','pK':'probably killed','?R':'possibly resprouted','?K':'possibly killed','?r':'possibly a small proportion resprouted','?k':'possibly a small proportion killed'}
def fr(code):
    c=re.sub(r'\s','',code)
    if c in ('R','pR','?R'): return 'resprouter'
    if c in ('K','pK','?K'): return 'obligate'
    return c
def yrs(cell):
    v=re.sub(r'</?u>|\*\*','',cell).strip()
    if not v: return None
    m=re.match(r'At least (\d+) years',v)
    if m: return '>='+m.group(1)
    m=re.match(r'Less than (\d+) year',v)
    if m: return '<'+m.group(1)
    m=re.match(r'(?:c\.\s?)?\??(\d+(?:\.\d+)?)(?:–(\d+(?:\.\d+)?))?(\+)?\??\s?(y|w)',v)
    if not m or m.group(4)=='w': return None
    a,b,plus=m.group(1),m.group(2),m.group(3)
    if plus: return '>'+a
    return f"{a}-{b}" if b else a
def parse_name(n):
    q=[]; ex=False
    if n.startswith('(*?)'): n=n[4:]; q.append("printed '(*?)': possibly exotic, not marked introduced")
    elif n.startswith('*'): n=n[1:]; ex=True
    m=re.search(r'\s*\((s\.lat\.|s\.str\.|syn\. [^)]*|hybrid)\)$',n)
    if m and 'hybrid' not in m.group(1): q.append(f"name qualifier '({m.group(1)})' as printed"); n=n[:m.start()]
    n=n.replace('“','').replace('”','')
    g,rest=n.split(' ',1)
    m=re.match(r'(.+?) ((?:subsp|var|cv)\. .+)$',rest)
    sp,ss=(m.group(1),m.group(2)) if m else (rest,'')
    return g,sp,ss,ex,q
COLN=['Family','Species','Post-fire fl, fr peaks','LCR','NL','Seedlings first observed','First flowering Resp','First flowering Seed','First fruiting Resp','First fruiting Seed','Primary juvenile period','Secondary juvenile period']
total=0
for b0,b1 in ((15,24),(25,34),(35,35)):
    out=[]
    for pi in range(b0,b1+1):
        for l in pages[pi-1].split('\n'):
            if not l.startswith('|') or l.startswith('| Family') or set(l)<=set('|- '): continue
            c=[x.strip() for x in l.strip().strip('|').split('|')]
            assert len(c)==12,(pi,l)
            fam,name=c[0],c[1]
            g,sp,ss,ex,q=parse_name(name)
            base={'Genus':g,'Species':sp,'subsp':('*' if ex and not ss else (ss+' *' if ex else ss)),'scientific_name':f"{g} {sp}"+(' *' if ex else ''),'Family':fam,'Source':src,'File_name':stem}
            base.update(FIRE)
            if ss and ex: q.append("introduced (*) and infraspecific name both in subsp")
            # time columns
            und=lambda v:'<u>' in v
            tv={}
            flR,flS,pj,sj=c[6],c[7],c[10],c[11]
            bridge_fl = und(flR) and flR==flS
            raw=[f"{COLN[k]}: {re.sub(r'</?u>','_',c[k]).replace('**','(bold)')}" for k in range(2,12) if k not in (3,4) and c[k]]
            areas=[(a,c[k]) for a,k in (('LCR',3),('NL',4))]
            resp={a:v for a,v in areas if v and not v.startswith('The host')}
            textnotes=[f"{a} cell: {v}" for a,v in areas if v.startswith('The host') or len(v)>12]
            def response_kind():
                vals=[fr(v[:4] if v.startswith('R(1)') else v.split('–')[0].split(';')[0]) for v in resp.values()]
                return vals
            kinds=response_kind()
            t={}
            if bridge_fl:
                y=yrs(flR)
                if y:
                    if kinds and all(k=='obligate' for k in kinds): t['Age at first flower production from seed_repr3']=y; q.append("underlined first-flowering value (seed or resprout unclear) assigned to repr3 because species killed")
                    elif kinds and all(k=='resprouter' for k in kinds): t['Time to first flower production resprout_repr3a']=y; q.append("underlined first-flowering value (seed or resprout unclear) assigned to repr3a because species resprouted")
                    else: q.append("underlined first-flowering value bridges Resp and Seed (origin unclear); not assigned")
            else:
                y=yrs(flS)
                if y: t['Age at first flower production from seed_repr3']=y
                y=yrs(flR)
                if y: t['Time to first flower production resprout_repr3a']=y
            y=yrs(pj)
            if y: t['primary_juvenile_period']=y
            y=yrs(sj)
            if y: t['secondary_juvenile_period']=y; t['Time_unit']='years'
            approx=any(re.search(r'c\.',re.sub(r'</?u>|\*\*','',x)) for x in (flR,flS,pj,sj) if x)
            haswk=any(re.match(r'(?:<u>)?\??\d',x) and yrs(x) is None for x in (flR,flS,pj,sj) if x)
            tnotes=[]
            if raw: tnotes.append(f"Appendix 1 (p. {130+pi}) timing as printed: "+"; ".join(raw))
            if t and approx: tnotes.append("'c.' = approximately")
            if haswk: tnotes.append("values in weeks (w) kept in Notes only: no unit rule for weeks")
            if t.get('primary_juvenile_period','').startswith('>='): tnotes.append("'At least 5 years' written as >=5")
            if any(v.startswith('>') and not v.startswith('>=') for v in t.values()): tnotes.append("'N+y' written as >N")
            if re.search(r'\?',pj+sj): tnotes.append("'?' in printed juvenile period: uncertain value")
            if 'shd' in pj+sj or 'fruit' in pj+sj or 'ripe' in pj+sj or 'grn' in pj+sj: tnotes.append("juvenile period based on fruiting or seed shedding as marked")
            # rows
            targets=list(resp.keys())
            timing_area= 'LCR' if 'LCR' in resp else ('NL' if 'NL' in resp else None)
            if not targets: targets=[None]
            for a in targets:
                row=dict(base); nt=[]
                if a=='LCR': row.update(LCR); nt.append("Lane Cove River catchment (LCR)")
                elif a=='NL': row['Location_name']='Narrabeen Lagoon catchment'; nt.append("Narrabeen Lagoon catchment (NL); no coordinates given")
                else: row['Location_name']='Lane Cove River and Narrabeen Lagoon catchments'; nt.append("no fire response given for either catchment")
                if a:
                    code=resp[a]
                    if code.startswith('R(1)'): row['fire_response categorical_surv1']='resprouter'; nt.append(f"{a} response as printed: '{code}'")
                    elif code.startswith('K;r'): row['fire_response categorical_surv1']='K;r'; nt.append(f"{a} response as printed: '{code}' (m.i.f = moderate intensity fire)")
                    else:
                        row['fire_response categorical_surv1']=fr(code)
                        cc=re.sub(r'\s','',code)
                        if cc not in ('R','K'): nt.append(f"{a} response code '{cc}' ("+", ".join(CODES.get(x,x) for x in cc.split('/'))+")")
                if a==timing_area or a is None:
                    row.update(t); nt+=tnotes
                    if t and len(targets)>1: nt.append("Appendix 1 timing not split by catchment; timing values placed on LCR row (LCR observed Jan 1994-Oct 1999, NL Mar-Oct 1994)")
                elif raw: nt.append("timing values for this species are on the LCR row")
                nt+=textnotes+q+[FNOTE]
                row['Notes']="; ".join(nt)
                out.append(row)
    with open(R,'a',newline='',encoding='utf-8') as fh:
        csv.DictWriter(fh,fieldnames=cols,lineterminator='\n').writerows(out)
    total+=len(out)
    print(f"    pages {b0}-{b1} of 35 | rows {total}")
EOF

